// ============================================================================ // 2. SETTINGS (single source of truth, saved automatically) // ============================================================================ final GameSettings cfg = GameSettings.I;

class GameSettings extends ChangeNotifier { static final GameSettings I = GameSettings.(); GameSettings.();

String lang = 'th'; int fps = 30; // 30 / 45 / 60 int shadow = 1; // 0 off, 1 low, 2 high double res = 0.75; // 0.5 / 0.75 / 1.0 (image detail level) int viewDist = 1; // 0 low, 1 mid, 2 high (NPC count + sim radius) bool showFps = false; bool haptic = true; bool leftHanded = false; int atkMode = 0; // 0 tap, 1 hold, 2 auto int atkSize = 1; double atkOpacity = 0.75; int joySize = 1; double joyOpacity = 0.6; bool joyFloating = false; Offset joyPos = const Offset(0.13, 0.74); Offset atkPos = const Offset(0.88, 0.72); Offset runPos = const Offset(0.75, 0.86);

double get atkPx => const [64.0, 80.0, 98.0][atkSize]; double get runPx => atkPx * 0.78; double get joyPx => const [110.0, 140.0, 170.0][joySize];

void update(void Function() f) { f(); notifyListeners(); _save(); }

void live(void Function() f) { f(); notifyListeners(); }

void commit() => _save();

void applyDefaultLayout() { if (leftHanded) { joyPos = const Offset(0.87, 0.74); atkPos = const Offset(0.12, 0.72); runPos = const Offset(0.25, 0.86); } else { joyPos = const Offset(0.13, 0.74); atkPos = const Offset(0.88, 0.72); runPos = const Offset(0.75, 0.86); } }

void resetGraphics() { update(() { fps = 30; shadow = 1; res = 0.75; viewDist = 1; showFps = false; }); }

void resetControls() { update(() { leftHanded = false; atkMode = 0; atkSize = 1; atkOpacity = 0.75; joySize = 1; joyOpacity = 0.6; joyFloating = false; haptic = true; applyDefaultLayout(); }); }

void autoTune(double raw) { update(() { if (raw >= 56) { fps = 60; shadow = 2; res = 1.0; viewDist = 2; } else if (raw >= 40) { fps = 45; shadow = 1; res = 0.75; viewDist = 1; } else if (raw > 0) { fps = 30; shadow = 0; res = 0.5; viewDist = 0; } else { fps = 30; shadow = 1; res = 0.75; viewDist = 1; } }); }

Future load() async { try { final p = await SharedPreferences.getInstance(); int gi(String k, int d, int lo, int hi) { final v = p.getInt(k); return (v != null && v >= lo && v <= hi) ? v : d; } double gd(String k, double d, double lo, double hi) { final v = p.getDouble(k); return (v != null && v >= lo && v <= hi) ? v : d; } final l = p.getString('lang'); if (l != null && kLangNames.containsKey(l)) lang = l; final f = p.getInt('fps'); if (f != null && (f == 30 || f == 45 || f == 60)) fps = f; final r = p.getDouble('res'); if (r != null && (r == 0.5 || r == 0.75 || r == 1.0)) res = r; shadow = gi('shadow', shadow, 0, 2); viewDist = gi('view', viewDist, 0, 2); showFps = p.getBool('showfps') ?? showFps; haptic = p.getBool('haptic') ?? haptic; leftHanded = p.getBool('left') ?? leftHanded; atkMode = gi('atkmode', atkMode, 0, 2); atkSize = gi('atksize', atkSize, 0, 2); atkOpacity = gd('atkop', atkOpacity, 0.2, 1.0); joySize = gi('joysize', joySize, 0, 2); joyOpacity = gd('joyop', joyOpacity, 0.2, 1.0); joyFloating = p.getBool('joyfloat') ?? joyFloating; Offset go(String k, Offset d) => Offset(gd('${k}x', d.dx, 0.04, 0.96), gd('${k}y', d.dy, 0.04, 0.96)); joyPos = go('joy', joyPos); atkPos = go('atk', atkPos); runPos = go('run', runPos); } catch (_) { // corrupted or unavailable storage -> keep defaults } }

Future save() async { try { final p = await SharedPreferences.getInstance(); await p.setString('lang', lang); await p.setInt('fps', fps); await p.setDouble('res', res); await p.setInt('shadow', shadow); await p.setInt('view', viewDist); await p.setBool('showfps', showFps); await p.setBool('haptic', haptic); await p.setBool('left', leftHanded); await p.setInt('atkmode', atkMode); await p.setInt('atksize', atkSize); await p.setDouble('atkop', atkOpacity); await p.setInt('joysize', joySize); await p.setDouble('joyop', joyOpacity); await p.setBool('joyfloat', joyFloating); await p.setDouble('joyx', joyPos.dx); await p.setDouble('joyy', joyPos.dy); await p.setDouble('atkx', atkPos.dx); await p.setDouble('atky', atkPos.dy); await p.setDouble('runx', runPos.dx); await p.setDouble('runy', runPos.dy); } catch () {} } }

// ============================================================================ // 3. SPECIES + FOOD CHAIN (data only, separate from AI code) // ============================================================================ class Species { final String id, emoji; final double hp, atk, speed, size, neckX, neckY, head, tail; final bool carn; final Color c1, c2; final List w; // spawn weight per biome: grass, forest, desert, swamp const Species(this.id, this.emoji, this.hp, this.atk, this.speed, this.size, this.carn, this.c1, this.c2, this.neckX, this.neckY, this.head, this.tail, this.w); }

const List kSpecies = [ Species('trex', '🦖', 320.0, 46.0, 125.0, 44.0, true, Color(0xFF8A5A3C), Color(0xFF5E3B26), 0.15, 0.12, 0.95, 1.7, [1.0, 1.0, 2.0, 0.5]), Species('allo', '🦖', 230.0, 34.0, 140.0, 36.0, true, Color(0xFFB5651D), Color(0xFF7A3E12), 0.2, 0.18, 0.75, 1.7, [1.5, 2.0, 1.0, 0.5]), Species('raptor', '🦎', 90.0, 16.0, 200.0, 20.0, true, Color(0xFFD4883A), Color(0xFF8F4F1A), 0.2, 0.22, 0.65, 1.9, [2.0, 1.0, 3.0, 0.5]), Species('dilo', '🦎', 110.0, 14.0, 150.0, 22.0, true, Color(0xFF4C9E6E), Color(0xFF2F6B48), 0.2, 0.28, 0.6, 1.8, [1.0, 1.0, 1.0, 3.0]), Species('trice', '🦏', 260.0, 30.0, 105.0, 34.0, false, Color(0xFF7E8F5B), Color(0xFF55643A), 0.12, -0.02, 0.9, 1.3, [3.0, 2.0, 1.0, 1.0]), Species('stego', '🦕', 240.0, 28.0, 95.0, 32.0, false, Color(0xFF6A8CAF), Color(0xFF3F5E80), 0.05, -0.1, 0.45, 1.5, [2.0, 3.0, 1.0, 1.0]), Species('para', '🦕', 150.0, 8.0, 175.0, 28.0, false, Color(0xFFC9A04B), Color(0xFF8B6A22), 0.25, 0.35, 0.65, 1.5, [4.0, 2.0, 1.0, 2.0]), Species('brachio', '🦕', 480.0, 20.0, 70.0, 54.0, false, Color(0xFF8E9AAF), Color(0xFF5F6B82), 0.55, 1.1, 0.5, 1.6, [2.0, 2.0, 0.5, 3.0]), Species('compy', '🐤', 35.0, 5.0, 190.0, 13.0, false, Color(0xFF9CCC65), Color(0xFF689F38), 0.15, 0.2, 0.55, 1.6, [4.0, 3.0, 3.0, 3.0]), ];

// Who hunts whom (carnivores). const Map<String, Set> kPrey = { 'trex': {'allo', 'trice', 'stego', 'raptor', 'dilo', 'para', 'compy'}, 'allo': {'stego', 'raptor', 'dilo', 'para', 'compy'}, 'raptor': {'dilo', 'compy', 'para'}, 'dilo': {'compy'}, }; // Who fights back instead of fleeing (herbivore defenders). const Map<String, Set> kDefends = { 'trice': {'raptor', 'dilo', 'allo'}, 'stego': {'raptor', 'dilo', 'compy'}, 'brachio': {'raptor', 'dilo', 'compy'}, }; // Special rules: T-Rex can only bring down a Brachiosaurus when it is below // 50% HP. A Raptor pack (3+) can beat a T-Rex.

// ============================================================================ // 4. WORLD (infinite, generated in chunks) // ============================================================================ const double kChunk = 512.0;

const List kBiome = [ Color(0xFF6FAE3E), Color(0xFF4C8B35), Color(0xFFDDB96B), Color(0xFF5B7B4C), ]; final List kBiomeD = kBiome.map((c) => shade(c, -0.06).withValues(alpha: 0.55)).toList(); final List kBiomeL = kBiome.map((c) => shade(c, 0.06).withValues(alpha: 0.5)).toList();

class Obstacle { final int type; // 0 tree, 1 rock, 2 pond, 3 bush final double x, y, cr, rad, scale; final int variant; double readyAt = 0; // bush: game time when berries are back Obstacle(this.type, this.x, this.y, this.cr, this.rad, this.scale, this.variant); }

class Chunk { final int cx, cy, biome; final List obs = []; final List patches = []; // x,y,r final List tufts = []; // x,y Chunk(this.cx, this.cy, this.biome); }

class World { final int seed; World(this.seed); final Map<(int, int), Chunk> _chunks = {};

Chunk chunk(int cx, int cy) => _chunks.putIfAbsent((cx, cy), () => _gen(cx, cy));

void prune(double px, double py) { final pcx = (px / kChunk).floor(), pcy = (py / kChunk).floor(); _chunks.removeWhere((k, v) => (k.$1 - pcx).abs() > 5 || (k.$2 - pcy).abs() > 5); }

int _hash(int a, int b, int c) { int h = (a * 374761393) ^ (b * 668265263) ^ (c * 1274126177) ^ (seed * 2246822519); h = (h ^ (h >> 13)) * 1274126177; h = h ^ (h >> 16); return h & 0x7fffffff; }

double _lat(int x, int y, int salt) => (_hash(x, y, salt) % 1000) / 1000.0;

double _noise(double x, double y, int salt) { final x0 = x.floor(), y0 = y.floor(); double fx = x - x0, fy = y - y0; fx = fx * fx * (3 - 2 * fx); fy = fy * fy * (3 - 2 * fy); final a = _lat(x0, y0, salt), b = _lat(x0 + 1, y0, salt); final c = _lat(x0, y0 + 1, salt), d = _lat(x0 + 1, y0 + 1, salt); final top = a + (b - a) * fx, bot = c + (d - c) * fx; return top + (bot - top) * fy; }

int biomeAtChunk(int cx, int cy) { if (cx == 0 && cy == 0) return 0; final n1 = _noise(cx * 0.22, cy * 0.22, 11); final n2 = _noise(cx * 0.22 + 50, cy * 0.22 + 50, 23); if (n1 < 0.27) return 2; if (n2 > 0.7) return 3; if (n2 < 0.36) return 1; return 0; }

int biomeAt(double x, double y) => biomeAtChunk((x / kChunk).floor(), (y / kChunk).floor());

bool _place(Chunk ch, Random r, int type, double cr, double rad, double scale, int variant, double margin) { for (int t = 0; t < 8; t++) { final x = ch.cx * kChunk + margin + r.nextDouble() * (kChunk - 2 * margin); final y = ch.cy * kChunk + margin + r.nextDouble() * (kChunk - 2 * margin); if (x * x + y * y < 170 * 170) continue; // keep spawn point clear bool ok = true; for (final o in ch.obs) { final dx = o.x - x, dy = o.y - y; final m = o.cr + cr + 16; if (dx * dx + dy * dy < m * m) { ok = false; break; } } if (ok) { ch.obs.add(Obstacle(type, x, y, cr, rad, scale, variant)); return true; } } return false; }

Chunk _gen(int cx, int cy) { final b = biomeAtChunk(cx, cy); final ch = Chunk(cx, cy, b); final r = Random(_hash(cx, cy, 99)); if (r.nextDouble() < const [0.3, 0.15, 0.08, 0.9][b]) { final n = b == 3 ? 1 + r.nextInt(2) : 1; for (int i = 0; i < n; i++) { final rad = 48 + r.nextDouble() * 40; _place(ch, r, 2, rad * 0.8, rad, 1.0, 0, rad + 14); } } final trees = const [4, 10, 1, 4][b] + r.nextInt(2); for (int i = 0; i < trees; i++) { int v; if (b == 2) { v = 2; } else if (b == 3) { v = 3; } else { v = r.nextInt(2); } _place(ch, r, 0, 13, 20, 0.8 + r.nextDouble() * 0.5, v, 30); } final rocks = const [2, 3, 6, 1][b]; for (int i = 0; i < rocks; i++) { final rad = 14 + r.nextDouble() * 16; _place(ch, r, 1, rad * 0.9, rad, 1.0, r.nextInt(5), 30); } final bushes = const [4, 3, 1, 3][b]; for (int i = 0; i < bushes; i++) { _place(ch, r, 3, 12, 14, 1.0, 0, 30); } for (int i = 0; i < 4; i++) { ch.patches.addAll([ cx * kChunk + r.nextDouble() * kChunk, cy * kChunk + r.nextDouble() * kChunk, 40 + r.nextDouble() * 70, ]); } for (int i = 0; i < 28; i++) { ch.tufts.addAll([ cx * kChunk + r.nextDouble() * kChunk, cy * kChunk + r.nextDouble() * kChunk, ]); } return ch; } }

// ============================================================================ // 5. GAME ENTITIES + ENGINE // ============================================================================ class Dino { final Species sp; final bool isPlayer; final int variant; double x, y, vx = 0, vy = 0; double hp; final double maxHp; double hunger = 100, stamina = 100; bool faceRight = true, dead = false, removed = false; double anim = 0, cd = 0, atkAnim = 0, flash = 0, corpse = 0, food = 0; double thinkT = 0, stateT = 0, aggroT = 0, wanderAng = 0, eatT = 0; int state = 0; // 0 idle, 1 wander, 2 flee, 3 hunt/fight, 4 eat, 5 forage Dino? target, aggro; Obstacle? bush; late final Color col1 = tintC(sp.c1, variant); late final Color col2 = tintC(sp.c2, variant);

Dino(this.sp, this.x, this.y, {this.isPlayer = false, this.variant = 0}) : hp = sp.hp, maxHp = sp.hp;

double get r => sp.size * 0.45; }

enum Phase { playing, over }

class FloatText { double x, y, ttl = 0.9; final String text; final Color color; FloatText(this.x, this.y, this.text, this.color); }

class Particle { double x, y, vx, vy, ttl, life; final double size; final Color color; Particle(this.x, this.y, this.vx, this.vy, this.life, this.size, this.color) : ttl = life; }

class DinoGame extends ChangeNotifier { final Random rng = Random(); late final World world; late final Dino player; final List dinos = []; final List texts = []; final List parts = []; Phase phase = Phase.playing; bool paused = false; double time = 20, survived = 0, cx = 0, cy = 0; double spawnT = 0, pruneT = 0, fpsT = 0, rawFps = 0, hapticT = 0, dustT = 0; int fpsN = 0, kills = 0; Offset joy = Offset.zero; bool run = false, atkHeld = false, exhausted = false; double atkBuf = 0;

DinoGame(Species sp, int variant) { world = World(Random().nextInt(1 << 30)); player = Dino(sp, 0, 0, isPlayer: true, variant: variant); dinos.add(player); final n = (maxNpc * 0.6).round(); for (int i = 0; i < n; i++) { _spawnOne(true); } }

int get maxNpc => const [16, 26, 36][cfg.viewDist]; double get simR => const [800.0, 1100.0, 1400.0][cfg.viewDist];

void repaint() => notifyListeners();

// ---------- helpers ---------- double _dist(Dino a, Dino b) { final dx = a.x - b.x, dy = a.y - b.y; return sqrt(dx * dx + dy * dy); }

bool canPrey(Dino a, Dino b) { final set = kPrey[a.sp.id]; if (set == null) return false; if (set.contains(b.sp.id)) return true; return a.sp.id == 'trex' && b.sp.id == 'brachio' && b.hp < b.maxHp * 0.5; }

bool _defends(Dino a, Dino b) => kDefends[a.sp.id]?.contains(b.sp.id) ?? false;

double _reach(Dino a, Dino b) => a.sp.size * 0.95 + b.sp.size * 0.55 + 8;

int _packNear(Dino d) { int n = 0; for (final o in dinos) { if (!o.dead && o.sp.id == 'raptor' && _dist(o, d) < 170) n++; } return n; }

bool _blocked(double x, double y, double r) { final ccx = (x / kChunk).floor(), ccy = (y / kChunk).floor(); for (int i = -1; i <= 1; i++) { for (int j = -1; j <= 1; j++) { final ch = world.chunk(ccx + i, ccy + j); for (final o in ch.obs) { if (o.type == 3) continue; final m = r + o.cr; final dx = x - o.x, dy = y - o.y; if (dx * dx + dy * dy < m * m) return true; } } } for (final d in dinos) { if (d.dead) continue; final dx = x - d.x, dy = y - d.y; if (dx * dx + dy * dy < 45 * 45) return true; } return false; }

void _collide(Dino d) { final r = d.r; final ccx = (d.x / kChunk).floor(), ccy = (d.y / kChunk).floor(); for (int i = -1; i <= 1; i++) { for (int j = -1; j <= 1; j++) { final ch = world.chunk(ccx + i, ccy + j); for (final o in ch.obs) { if (o.type == 3) continue; final rr = r + o.cr; final dx = d.x - o.x, dy = d.y - o.y; final d2 = dx * dx + dy * dy; if (d2 < rr * rr) { final dist = sqrt(d2); if (dist < 0.001) { d.x = o.x + rr; } else { d.x = o.x + dx / dist * rr; d.y = o.y + dy / dist * rr; } } } } } }

Obstacle? _nearestBush(double x, double y, double maxD) { Obstacle? best; double bd = maxD; final ccx = (x / kChunk).floor(), ccy = (y / kChunk).floor(); for (int i = -1; i <= 1; i++) { for (int j = -1; j <= 1; j++) { for (final o in world.chunk(ccx + i, ccy + j).obs) { if (o.type != 3 || o.readyAt > time) continue; final dx = o.x - x, dy = o.y - y; final dd = sqrt(dx * dx + dy * dy); if (dd < bd) { bd = dd; best = o; } } } } return best; }

Dino? _nearestCorpse(Dino d, double maxD) { Dino? best; double bd = maxD; for (final o in dinos) { if (!o.dead || o.removed || o.food <= 0) continue; final dd = _dist(d, o); if (dd < bd) { bd = dd; best = o; } } return best; }

Dino? _nearestTarget(Dino p) { Dino? best; double bd = 1e9; for (final o in dinos) { if (identical(o, p) || o.dead) continue; final dd = _dist(p, o); if (dd <= _reach(p, o) && dd < bd) { bd = dd; best = o; } } return best; }

void _text(double x, double y, String s, Color c) { if (texts.length < 30) texts.add(FloatText(x, y, s, c)); }

void _burst(double x, double y, int n, Color c) { for (int i = 0; i < n && parts.length < 150; i++) { final a = rng.nextDouble() * 2 * pi; final s = 30 + rng.nextDouble() * 70; parts.add(Particle(x, y, cos(a) * s, sin(a) * s - 20, 0.4 + rng.nextDouble() * 0.3, 2 + rng.nextDouble() * 2, c)); } }

void _haptic(bool strong) { if (!cfg.haptic || hapticT > 0) return; hapticT = 0.08; if (strong) { HapticFeedback.mediumImpact(); } else { HapticFeedback.lightImpact(); } }

// ---------- spawning ---------- Species _pick(int biome) { double total = 0; for (final s in kSpecies) { total += s.w[biome]; } double roll = rng.nextDouble() * total; for (final s in kSpecies) { roll -= s.w[biome]; if (roll <= 0) return s; } return kSpecies.last; }

bool _spawnOne(bool initial) { for (int t = 0; t < 6; t++) { final ang = rng.nextDouble() * 2 * pi; final dist = initial ? 350 + rng.nextDouble() * 650 : simR * 0.8 + rng.nextDouble() * simR * 0.15; final x = player.x + cos(ang) * dist, y = player.y + sin(ang) * dist; final sp = _pick(world.biomeAt(x, y)); if (_blocked(x, y, sp.size * 0.5)) continue; final n = sp.id == 'raptor' ? 2 + rng.nextInt(2) : 1; for (int k = 0; k < n; k++) { if (dinos.length - 1 >= maxNpc + 3) break; final px = x + (k == 0 ? 0.0 : (rng.nextDouble() - 0.5) * 90); final py = y + (k == 0 ? 0.0 : (rng.nextDouble() - 0.5) * 90); if (k > 0 && _blocked(px, py, sp.size * 0.5)) continue; final d = Dino(sp, px, py, variant: rng.nextInt(3)); d.hunger = 40 + rng.nextDouble() * 60; d.stateT = rng.nextDouble() * 2; d.thinkT = rng.nextDouble() * 0.3; dinos.add(d); } return true; } return false; }

// ---------- combat ---------- void _hit(Dino a, Dino b) { double m; if (kPrey[a.sp.id]?.contains(b.sp.id) ?? false) { m = 1.0; } else if (_defends(a, b)) { m = (a.sp.id == 'trice' && b.sp.id == 'allo') ? 1.4 : 1.25; } else if (a.sp.id == 'trex' && b.sp.id == 'brachio') { m = b.hp < b.maxHp * 0.5 ? 1.0 : 0.35; } else { m = 0.4; } if (a.sp.id == 'raptor' && b.sp.id == 'trex') { m = _packNear(b) >= 3 ? 2.2 : 0.25; } final dmg = a.sp.atk * m * (0.85 + rng.nextDouble() * 0.3); b.hp -= dmg; b.flash = 0.15; final dx = b.x - a.x, dy = b.y - a.y; final l = max(1.0, sqrt(dx * dx + dy * dy)); b.x += dx / l * 8; b.y += dy / l * 8; _text(b.x, b.y - b.sp.size * 1.5, '-${dmg.round()}', a.isPlayer ? Colors.yellowAccent : Colors.redAccent); _burst(b.x, b.y - b.sp.size * 0.6, 6, Colors.orangeAccent); if (a.isPlayer || b.isPlayer) _haptic(true); if (b.hp <= 0) { _kill(b, a); } else { b.aggro = a; b.aggroT = 6; b.thinkT = 0; } }

void _kill(Dino b, Dino a) { b.hp = 0; b.dead = true; b.corpse = 22; b.food = b.sp.size * 2.2; b.vx = 0; b.vy = 0; b.target = null; if (a.isPlayer) kills++; if (b.isPlayer) { phase = Phase.over; _haptic(true); } }

void _eat(Dino p, double amount, Dino? corpse) { p.hunger = min(100.0, p.hunger + amount); p.hp = min(p.maxHp, p.hp + 5); p.atkAnim = 0.25; p.cd = 0.45; if (corpse != null) { corpse.food -= amount; if (corpse.food <= 0) corpse.corpse = 0.01; } _text(p.x, p.y - p.sp.size * 1.6, '+${amount.round()}', Colors.lightGreenAccent); _burst(p.x + (p.faceRight ? 1 : -1) * p.sp.size, p.y - p.sp.size * 0.4, 5, Colors.lightGreen); _haptic(false); }

void _playerAct(Dino p) { final t = _nearestTarget(p); if (t != null) { _hit(p, t); p.cd = 0.55; p.atkAnim = 0.3; if ((t.x - p.x).abs() > 3) p.faceRight = t.x > p.x; return; } if (p.sp.carn) { Dino? c; double best = 1e9; for (final o in dinos) { if (o.dead && !o.removed && o.food > 0) { final d = _dist(p, o); if (d < _reach(p, o) + 25 && d < best) { best = d; c = o; } } } if (c != null) { _eat(p, 18, c); return; } } else { final b = _nearestBush(p.x, p.y, 55 + p.sp.size * 0.5); if (b != null) { b.readyAt = time + 40; _eat(p, 25, null); return; } } p.cd = 0.35; p.atkAnim = 0.2; _haptic(false); }

// ---------- main update ---------- void update(double dt) { if (phase != Phase.playing || paused) return; time += dt; survived += dt; _updatePlayer(dt); if (phase != Phase.playing) return; for (int i = 1; i < dinos.length; i++) { final d = dinos[i]; if (d.dead) { d.corpse -= dt; continue; } _npcUpdate(d, dt); } _separate(); for (final d in dinos) { if (!d.dead) _collide(d); } // despawn for (int i = dinos.length - 1; i >= 1; i--) { final d = dinos[i]; final far = _dist(d, player) > simR * 1.25; if ((d.dead && d.corpse <= 0) || far) { d.removed = true; dinos.removeAt(i); } } spawnT -= dt; if (spawnT <= 0) { spawnT = 0.6; int alive = 0; for (final d in dinos) { if (!d.isPlayer && !d.dead) alive++; } if (alive < maxNpc) _spawnOne(false); } pruneT -= dt; if (pruneT <= 0) { pruneT = 3; world.prune(player.x, player.y); } hapticT = max(0.0, hapticT - dt); for (int i = parts.length - 1; i >= 0; i--) { final q = parts[i]; q.ttl -= dt; if (q.ttl <= 0) { parts.removeAt(i); continue; } q.x += q.vx * dt; q.y += q.vy * dt; q.vy += 60 * dt; } for (int i = texts.length - 1; i >= 0; i--) { final t = texts[i]; t.ttl -= dt; t.y -= 28 * dt; if (t.ttl <= 0) texts.removeAt(i); } final k = min(1.0, dt * 8); cx += (player.x - cx) * k; cy += (player.y - cy) * k; }

void _updatePlayer(double dt) { final p = player; p.cd = max(0.0, p.cd - dt); p.atkAnim = max(0.0, p.atkAnim - dt); p.flash = max(0.0, p.flash - dt); atkBuf = max(0.0, atkBuf - dt); p.hunger = max(0.0, p.hunger - 0.35 * dt); if (p.hunger <= 0) { p.hp -= 2.0 * dt; if (p.hp <= 0) { p.hp = 0; p.dead = true; phase = Phase.over; return; } } else if (p.hunger > 60 && p.hp < p.maxHp) { p.hp = min(p.maxHp, p.hp + 1.5 * dt); } final len = sqrt(joy.dx * joy.dx + joy.dy * joy.dy); final moving = len > 0.12; double mult = 1.0; if (run && moving && !exhausted && p.stamina > 0) { mult = 1.55; p.stamina = max(0.0, p.stamina - 24 * dt); if (p.stamina <= 0) exhausted = true; } else { p.stamina = min(100.0, p.stamina + 16 * dt); if (exhausted && p.stamina > 30) exhausted = false; } final tvx = moving ? joy.dx * p.sp.speed * mult : 0.0; final tvy = moving ? joy.dy * p.sp.speed * mult : 0.0; final k = min(1.0, dt * 10); p.vx += (tvx - p.vx) * k; p.vy += (tvy - p.vy) * k; p.x += p.vx * dt; p.y += p.vy * dt; _collide(p); final sp2 = p.vx * p.vx + p.vy * p.vy; if (sp2 > 25) { final s = sqrt(sp2); p.anim += dt * (4 + s * 0.06); if (p.vx.abs() > 3) p.faceRight = p.vx > 0; dustT -= dt; if (dustT <= 0 && mult > 1.0) { dustT = 0.07; if (parts.length < 150) { parts.add(Particle(p.x - (p.faceRight ? 1 : -1) * p.sp.size * 0.5, p.y - 2, (rng.nextDouble() - 0.5) * 20, -15 - rng.nextDouble() * 15, 0.5, 3 + rng.nextDouble() * 2, const Color(0x88C8B48A))); } } } bool want = atkBuf > 0 || (cfg.atkMode == 1 && atkHeld); if (!want && cfg.atkMode == 2 && _nearestTarget(p) != null) want = true; if (want && p.cd <= 0) { atkBuf = 0; _playerAct(p); } }

void _separate() { final n = dinos.length; for (int i = 0; i < n; i++) { final a = dinos[i]; if (a.dead) continue; for (int j = i + 1; j < n; j++) { final b = dinos[j]; if (b.dead) continue; final dx = b.x - a.x, dy = b.y - a.y; final m = a.r + b.r; if (dx.abs() > m || dy.abs() > m) continue; final d2 = dx * dx + dy * dy; if (d2 >= m * m) continue; final d = sqrt(d2); final push = (m - d) * 0.5; double nx, ny; if (d < 0.01) { nx = 1; ny = 0; } else { nx = dx / d; ny = dy / d; } a.x -= nx * push; a.y -= ny * push; b.x += nx * push; b.y += ny * push; } } }

// ---------- NPC AI ---------- void _npcUpdate(Dino d, double dt) { d.cd = max(0.0, d.cd - dt); d.atkAnim = max(0.0, d.atkAnim - dt); d.flash = max(0.0, d.flash - dt); d.stateT -= dt; d.hunger = max(0.0, d.hunger - 1.2 * dt); if (d.aggroT > 0) d.aggroT -= dt; d.thinkT -= dt; if (d.thinkT <= 0) { d.thinkT = 0.25 + rng.nextDouble() * 0.2; _think(d); } _act(d, dt); }

void _think(Dino d) { final sp = d.sp; Dino? threat, prey; double td = 1e9, pd = 1e9; final sight = 280.0 + sp.size * 2; for (final o in dinos) { if (identical(o, d) || o.dead) continue; final dist = _dist(d, o); if (dist > sight) continue; if (canPrey(o, d) && dist < td) { td = dist; threat = o; } if (canPrey(d, o) && dist < pd) { pd = dist; prey = o; } } final ag = d.aggroT > 0 ? d.aggro : null; if (ag != null && !ag.dead && !ag.removed) { d.target = ag; final fight = _defends(d, ag) || (sp.carn && ag.sp.size <= sp.size * 1.3) || (sp.id == 'raptor' && ag.sp.id == 'trex' && _packNear(d) >= 3); d.state = fight ? 3 : 2; return; } if (threat != null && td < 230) { d.target = threat; d.state = (_defends(d, threat) && td < 180) ? 3 : 2; return; } if (sp.carn && d.hunger < 65) { if (prey != null) { d.target = prey; d.state = 3; return; } if (sp.id == 'raptor') { for (final o in dinos) { if (identical(o, d) || o.dead || o.sp.id != 'raptor' || o.state != 3) continue; final ot = o.target; if (ot != null && !ot.dead && !ot.removed && _dist(d, o) < 260 && _dist(d, ot) < 520) { d.target = ot; d.state = 3; return; } } } final c = _nearestCorpse(d, 350); if (c != null) { d.target = c; d.state = 4; return; } } if (!sp.carn && d.hunger < 70) { final b = _nearestBush(d.x, d.y, 420); if (b != null) { d.bush = b; d.state = 5; return; } } if (d.state == 0 || d.state == 1) { if (d.stateT <= 0) { if (rng.nextDouble() < 0.35) { d.state = 0; d.stateT = 1.5 + rng.nextDouble() * 3; } else { d.state = 1; d.wanderAng = rng.nextDouble() * 2 * pi; d.stateT = 2 + rng.nextDouble() * 4; } } } else { d.state = 0; d.stateT = 0.5; } }

void _act(Dino d, double dt) { final sp = d.sp; final t = d.target; double tx = 0, ty = 0, spd = 0; if (d.state == 1) { tx = cos(d.wanderAng); ty = sin(d.wanderAng); spd = 0.45; } else if (d.state == 2) { if (t != null && !t.dead && !t.removed) { final dx = d.x - t.x, dy = d.y - t.y; final l = sqrt(dx * dx + dy * dy); if (l > 1) { tx = dx / l; ty = dy / l; } spd = 1.15; } else { d.state = 0; } } else if (d.state == 3) { if (t == null || t.dead || t.removed) { if (t != null && t.dead && !t.removed && sp.carn && t.food > 0) { d.state = 4; } else { d.state = 0; d.target = null; } } else { final dx = t.x - d.x, dy = t.y - d.y; final l = sqrt(dx * dx + dy * dy); final reach = _reach(d, t); if (l > reach * 0.8 && l > 1) { tx = dx / l; ty = dy / l; spd = 1.0; } if (l <= reach && d.cd <= 0) { _hit(d, t); d.cd = 1.0 + rng.nextDouble() * 0.4; d.atkAnim = 0.3; } if (l > 480) { d.state = 0; d.target = null; } if (dx.abs() > 4) d.faceRight = dx > 0; } } else if (d.state == 4) { if (t == null || t.removed || t.food <= 0 || d.hunger >= 98) { d.state = 0; d.target = null; } else { final dx = t.x - d.x, dy = t.y - d.y; final l = sqrt(dx * dx + dy * dy); if (l > sp.size * 0.9) { tx = dx / max(l, 1.0); ty = dy / max(l, 1.0); spd = 0.8; } else { d.eatT += dt; d.atkAnim = max(d.atkAnim, 0.1); if (d.eatT >= 0.8) { d.eatT = 0; d.hunger = min(100.0, d.hunger + 14); t.food -= 14; d.hp = min(d.maxHp, d.hp + 4); if (t.food <= 0) t.corpse = 0.01; } } } } else if (d.state == 5) { final b = d.bush; if (b == null || b.readyAt > time) { d.state = 0; d.bush = null; } else { final dx = b.x - d.x, dy = b.y - d.y; final l = sqrt(dx * dx + dy * dy); if (l > 22) { tx = dx / l; ty = dy / l; spd = 0.8; } else { d.hunger = min(100.0, d.hunger + 40); b.readyAt = time + 40; d.state = 0; d.bush = null; } } } final k = min(1.0, dt * 6); d.vx += (tx * sp.speed * spd - d.vx) * k; d.vy += (ty * sp.speed * spd - d.vy) * k; d.x += d.vx * dt; d.y += d.vy * dt; final s2 = d.vx * d.vx + d.vy * d.vy; if (s2 > 25) { d.anim += dt * (4 + sqrt(s2) * 0.06); if (d.state != 3 && d.vx.abs() > 3) d.faceRight = d.vx > 0; } } }

// ============================================================================ // 6. DINOSAUR DRAWING (shared by game + preview) // ============================================================================ void drawDinoShape(Canvas c, Species sp, Color col, Color col2, double anim, double lunge, double flash, bool dead) { final u = sp.size; if (dead) { col = Color.lerp(col, const Color(0xFF777777), 0.6)!; col2 = Color.lerp(col2, const Color(0xFF555555), 0.6)!; } final p = Paint()..isAntiAlias = true; final dark = shade(col2, -0.08); final lp = Paint() ..color = dark ..style = PaintingStyle.stroke ..strokeCap = StrokeCap.round ..strokeWidth = u * 0.2; final sw = dead ? 0.0 : sin(anim) * u * 0.2; // far legs c.drawLine(Offset(-0.25 * u, -0.4 * u), Offset(-0.25 * u - sw, 0), lp); c.drawLine(Offset(0.45 * u, -0.4 * u), Offset(0.45 * u + sw, 0), lp); // tail final ts = dead ? 0.0 : sin(anim * 0.6) * 0.1 * u; final tail = Path() ..moveTo(-0.55 * u, -0.95 * u) ..quadraticBezierTo(-1.1 * u, -0.95 * u + ts, -sp.tail * u, -0.62 * u + ts * 1.5) ..quadraticBezierTo(-1.0 * u, -0.5 * u, -0.55 * u, -0.4 * u) ..close(); p.color = col2; c.drawPath(tail, p); // stegosaurus plates (behind body) if (sp.id == 'stego') { p.color = const Color(0xFFE67E22); for (int i = 0; i < 6; i++) { final x = -0.6 * u + i * 0.23 * u; final h = (0.3 + 0.12 * sin(i * 0.9 + 0.5)) * u; final pl = Path() ..moveTo(x - 0.1 * u, -1.0 * u) ..lineTo(x, -1.0 * u - h) ..lineTo(x + 0.1 * u, -1.0 * u) ..close(); c.drawPath(pl, p); } } // body final body = Rect.fromCenter(center: Offset(0, -0.65 * u), width: 1.7 * u, height: 0.9 * u); p.shader = LinearGradient( begin: Alignment.topCenter, end: Alignment.bottomCenter, colors: [shade(col, 0.12), col, shade(col, -0.15)], ).createShader(body); c.drawOval(body, p); p.shader = null; p.color = shade(col, 0.22).withValues(alpha: 0.5); c.drawOval(Rect.fromCenter(center: Offset(0.05 * u, -0.5 * u), width: 1.2 * u, height: 0.3 * u), p); if (sp.id == 'raptor') { final sp2 = Paint() ..color = dark.withValues(alpha: 0.7) ..strokeWidth = u * 0.07 ..strokeCap = StrokeCap.round; for (int i = 0; i < 3; i++) { final x = -0.4 * u + i * 0.3 * u; c.drawLine(Offset(x, -1.05 * u), Offset(x + 0.08 * u, -0.62 * u), sp2); } } // near legs lp.color = col2; c.drawLine(Offset(-0.45 * u, -0.4 * u), Offset(-0.45 * u + sw, 0), lp); c.drawLine(Offset(0.25 * u, -0.4 * u), Offset(0.25 * u - sw, 0), lp); // tiny arms for T-Rex if (sp.id == 'trex') { final ap = Paint() ..color = dark ..strokeWidth = u * 0.07 ..strokeCap = StrokeCap.round; c.drawLine(Offset(0.55 * u, -0.6 * u), Offset(0.72 * u, -0.48 * u), ap); } // neck + head final hx = 0.78 * u + sp.neckX * u + lunge * 0.3 * u; final hy = -0.82 * u - sp.neckY * u; final np = Paint() ..color = col ..style = PaintingStyle.stroke ..strokeCap = StrokeCap.round ..strokeWidth = u * (sp.id == 'brachio' ? 0.3 : 0.38); c.drawLine(Offset(0.5 * u, -0.85 * u), Offset(hx - 0.1 * u, hy), np); final hw = sp.head * u, hh = sp.head * u * 0.62; if (sp.id == 'trice') { p.color = col2; c.drawCircle(Offset(hx - 0.14 * u, hy), 0.52 * u, p); p.color = shade(col2, 0.12); c.drawCircle(Offset(hx - 0.14 * u, hy), 0.36 * u, p); } if (sp.id == 'para') { final cp = Paint() ..color = col2 ..style = PaintingStyle.stroke ..strokeCap = StrokeCap.round ..strokeWidth = u * 0.14; final cr = Path() ..moveTo(hx + hw * 0.1, hy - hh * 0.4) ..quadraticBezierTo(hx - hw * 0.2, hy - hh * 1.8, hx - hw * 1.0, hy - hh * 1.2); c.drawPath(cr, cp); } final headRect = Rect.fromCenter(center: Offset(hx, hy), width: hw, height: hh); p.shader = LinearGradient( begin: Alignment.topCenter, end: Alignment.bottomCenter, colors: [shade(col, 0.1), shade(col, -0.1)], ).createShader(headRect); c.drawOval(headRect, p); p.shader = null; if (sp.id == 'trice') { final hp2 = Paint() ..color = const Color(0xFFF5E6C8) ..strokeCap = StrokeCap.round ..strokeWidth = u * 0.09; c.drawLine(Offset(hx + hw * 0.1, hy - hh * 0.3), Offset(hx + hw * 0.55, hy - hh * 1.1), hp2); c.drawLine(Offset(hx + hw * 0.4, hy - hh * 0.05), Offset(hx + hw * 0.75, hy - hh * 0.45), hp2); } if (sp.id == 'dilo') { final cp = Paint() ..color = const Color(0xFFE53935) ..strokeCap = StrokeCap.round ..strokeWidth = u * 0.07; c.drawLine(Offset(hx - hw * 0.1, hy - hh * 0.45), Offset(hx + hw * 0.15, hy - hh * 0.95), cp); c.drawLine(Offset(hx + hw * 0.15, hy - hh * 0.45), Offset(hx + hw * 0.4, hy - hh * 0.9), cp); } // mouth + teeth final mp = Paint() ..color = dark ..strokeWidth = max(1.0, u * 0.03) ..strokeCap = StrokeCap.round; final mouthY = hy + hh * 0.2; c.drawLine(Offset(hx - hw * 0.05, mouthY), Offset(hx + hw * 0.48, mouthY - hh * 0.05), mp); if (sp.carn) { p.color = Colors.white; for (int i = 0; i < 3; i++) { final tx = hx + hw * (0.15 + i * 0.12); final tp = Path() ..moveTo(tx, mouthY) ..lineTo(tx + hw * 0.04, mouthY + hh * 0.22) ..lineTo(tx + hw * 0.08, mouthY) ..close(); c.drawPath(tp, p); } } // eye final ex = hx + hw * 0.15, ey = hy - hh * 0.12; final er = max(1.6, u * 0.055); if (dead) { final xp = Paint() ..color = Colors.black87 ..strokeWidth = 1.5; c.drawLine(Offset(ex - er, ey - er), Offset(ex + er, ey + er), xp); c.drawLine(Offset(ex - er, ey + er), Offset(ex + er, ey - er), xp); } else { p.color = Colors.white; c.drawCircle(Offset(ex, ey), er, p); p.color = Colors.black; c.drawCircle(Offset(ex + er * 0.25, ey), er * 0.55, p); } if (flash > 0) { p.color = Colors.white.withValues(alpha: min(0.7, flash * 5)); c.drawOval(body, p); c.drawOval(headRect, p); } }

// ============================================================================ // 7. GAME PAINTER // ============================================================================ class _DI { final double y; final Obstacle? o; final Dino? d; _DI(this.y, this.o, this.d); }

class GamePainter extends CustomPainter { final DinoGame g; GamePainter(this.g) : super(repaint: g); final Paint _p = Paint()..isAntiAlias = true; final Paint _st = Paint() ..isAntiAlias = true ..style = PaintingStyle.stroke ..strokeCap = StrokeCap.round; final List<_DI> _items = [];

@override void paint(Canvas c, Size size) { final zoom = size.height / 440.0; final hw = size.width / 2 / zoom, hh = size.height / 2 / zoom; final lod = cfg.res >= 0.99 ? 2 : (cfg.res >= 0.7 ? 1 : 0); final sh = cfg.shadow; final t = g.time; c.save(); c.translate(size.width / 2, size.height / 2); c.scale(zoom, zoom); c.translate(-g.cx, -g.cy); final x0 = ((g.cx - hw - 100) / kChunk).floor(); final x1 = ((g.cx + hw + 100) / kChunk).floor(); final y0 = ((g.cy - hh - 100) / kChunk).floor(); final y1 = ((g.cy + hh + 100) / kChunk).floor(); _items.clear(); for (int j = y0; j <= y1; j++) { for (int i = x0; i <= x1; i++) { _ground(c, g.world.chunk(i, j), lod); } } for (int j = y0; j <= y1; j++) { for (int i = x0; i <= x1; i++) { for (final o in g.world.chunk(i, j).obs) { if (o.type == 2) { _pond(c, o, t, lod); } else { _items.add(_DI(o.y, o, null)); } } } } for (final d in g.dinos) { if (d.x < g.cx - hw - 120 || d.x > g.cx + hw + 120 || d.y < g.cy - hh - 150 || d.y > g.cy + hh + 120) { continue; } _items.add(_DI(d.dead ? d.y - 40 : d.y, null, d)); } _items.sort((a, b) => a.y.compareTo(b.y)); for (final it in _items) { final o = it.o; if (o != null) { if (o.type == 0) { _tree(c, o, t, lod, sh); } else if (o.type == 1) { _rock(c, o, sh); } else { _bush(c, o, o.readyAt <= t); } } else { _dino(c, it.d!); } } for (final it in _items) { final d = it.d; if (d != null && !d.dead && (d.hp < d.maxHp || d.isPlayer)) { final by = d.y - d.sp.size * (1.75 + d.sp.neckY); _bar(c, d.x, by, 40, cl(d.hp / d.maxHp, 0, 1), d.isPlayer ? Colors.cyanAccent : Colors.redAccent); } } for (final q in g.parts) { _p.color = q.color.withValues(alpha: cl(q.ttl / q.life, 0, 1)); c.drawCircle(Offset(q.x, q.y), q.size, _p); } for (final tx in g.texts) { final tp = TextPainter( text: TextSpan( text: tx.text, style: TextStyle( color: tx.color.withValues(alpha: cl(tx.ttl * 2, 0, 1)), fontSize: 15, fontWeight: FontWeight.bold, shadows: const [Shadow(color: Colors.black, blurRadius: 3)], ), ), textDirection: TextDirection.ltr, )..layout(); tp.paint(c, Offset(tx.x - tp.width / 2, tx.y)); } c.restore(); // day / night + vignette (screen space) final rect = Offset.zero & size; final sun = sin(g.time / 300 * 2 * pi); final dark = cl((-sun - 0.15) / 0.85, 0, 1) * 0.55; if (dark > 0.01) { _p.color = Color.fromRGBO(10, 16, 56, dark); c.drawRect(rect, _p); } final dusk = cl(1 - sun.abs() / 0.25, 0, 1) * 0.16; if (dusk > 0.01) { _p.color = Color.fromRGBO(255, 120, 40, dusk); c.drawRect(rect, _p); } if (lod >= 1) { _p.shader = const RadialGradient( radius: 0.95, colors: [Color(0x00000000), Color(0x55000000)], ).createShader(rect); c.drawRect(rect, _p); _p.shader = null; } }

void _ground(Canvas c, Chunk ch, int lod) { final rect = Rect.fromLTWH(ch.cx * kChunk - 1, ch.cy * kChunk - 1, kChunk + 2, kChunk + 2); _p.color = kBiome[ch.biome]; c.drawRect(rect, _p); for (int i = 0; i < ch.patches.length; i += 3) { _p.color = (i % 6 == 0) ? kBiomeD[ch.biome] : kBiomeL[ch.biome]; final r = ch.patches[i + 2]; c.drawOval(Rect.fromCenter(center: Offset(ch.patches[i], ch.patches[i + 1]), width: r * 2, height: r * 1.2), _p); } if (lod >= 1) { _st.color = kBiomeD[ch.biome]; _st.strokeWidth = 1.3; final step = lod >= 2 ? 2 : 4; for (int i = 0; i < ch.tufts.length; i += step) { final x = ch.tufts[i], y = ch.tufts[i + 1]; c.drawLine(Offset(x, y), Offset(x - 2.5, y - 6), _st); c.drawLine(Offset(x, y), Offset(x + 2.5, y - 6), _st); } } }

void _pond(Canvas c, Obstacle o, double t, int lod) { final r = o.rad; final rect = Rect.fromCenter(center: Offset(o.x, o.y), width: r * 2.2, height: r * 1.6); _p.color = const Color(0xFFC9B27A); c.drawOval(rect.inflate(6), _p); _p.shader = const RadialGradient(colors: [Color(0xFF4FC3F7), Color(0xFF1E88E5)]).createShader(rect); c.drawOval(rect, _p); _p.shader = null; if (lod >= 1) { _st.strokeWidth = 1.5; for (int k = 0; k < 2; k++) { final ph = (t * 0.5 + k * 0.5 + o.x * 0.01) % 1.0; _st.color = Colors.white.withValues(alpha: (1 - ph) * 0.45); c.drawOval(Rect.fromCenter(center: Offset(o.x, o.y), width: r * 2.0 * ph, height: r * 1.4 * ph), _st); } } }

void _tree(Canvas c, Obstacle o, double t, int lod, int sh) { final h = o.scale, x = o.x, y = o.y; if (sh >= 2) { _p.color = const Color(0x33000000); c.drawOval(Rect.fromCenter(center: Offset(x + 12 * h, y), width: 62 * h, height: 16 * h), _p); } final sway = sin(t * 1.4 + x * 0.02) * 2.5; if (o.variant == 2) { _st.color = const Color(0xFF8D6E4A); _st.strokeWidth = 7 * h; final top = Offset(x + sway, y - 62 * h); c.drawLine(Offset(x, y), top, _st); _st.color = const Color(0xFF5FA845); _st.strokeWidth = 5 * h; for (int i = 0; i < 6; i++) { final a = -pi / 2 + (i - 2.5) * 0.6; c.drawLine(top, top + Offset(cos(a) * 34 * h, sin(a) * 22 * h + 8 * h), _st); } return; } _p.color = const Color(0xFF6D4C41); c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(x - 5 * h, y - 36 * h, 10 * h, 38 * h), const Radius.circular(3)), _p); if (o.variant == 1) { const cols = [Color(0xFF2B6E47), Color(0xFF2F7A4F), Color(0xFF3A8A5A)]; for (int i = 0; i < 3; i++) { final w = (36 - i * 8) * h; final by = y - (22 + i * 22) * h; _p.color = cols[i]; final path = Path() ..moveTo(x - w, by) ..lineTo(x + sway * 0.5, by - 36 * h) ..lineTo(x + w, by) ..close(); c.drawPath(path, _p); } return; } final base = o.variant == 3 ? const Color(0xFF2F5D3A) : const Color(0xFF3E8E41); final hi = o.variant == 3 ? const Color(0xFF3F7A4D) : const Color(0xFF56AC4E); _p.color = base; c.drawCircle(Offset(x + sway * 0.5, y - 52 * h), 30 * h, _p); if (lod >= 1) { c.drawCircle(Offset(x - 16 * h + sway, y - 44 * h), 20 * h, _p); c.drawCircle(Offset(x + 17 * h + sway, y - 46 * h), 21 * h, _p); _p.color = hi; c.drawCircle(Offset(x - 6 * h + sway, y - 62 * h), 17 * h, _p); } }

void _rock(Canvas c, Obstacle o, int sh) { final r = o.rad; if (sh >= 1) { _p.color = const Color(0x33000000); c.drawOval(Rect.fromCenter(center: Offset(o.x + 4, o.y + 2), width: r * 2.2, height: r * 0.7), _p); } final path = Path(); for (int i = 0; i < 7; i++) { final a = i / 7 * 2 * pi; final rr = r * (0.82 + 0.22 * sin(i * 2.3 + o.variant)); final px = o.x + cos(a) * rr, py = o.y - r * 0.4 + sin(a) * rr * 0.7; if (i == 0) { path.moveTo(px, py); } else { path.lineTo(px, py); } } path.close(); _p.color = const Color(0xFF8D949B); c.drawPath(path, _p); _p.color = const Color(0xFFB5BCC4); c.drawCircle(Offset(o.x - r * 0.25, o.y - r * 0.65), r * 0.28, _p); }

void _bush(Canvas c, Obstacle o, bool ready) { _p.color = const Color(0xFF2E7D32); c.drawCircle(Offset(o.x - 8, o.y - 8), 11, _p); c.drawCircle(Offset(o.x + 8, o.y - 8), 11, _p); _p.color = const Color(0xFF43A047); c.drawCircle(Offset(o.x, o.y - 14), 12, _p); if (ready) { _p.color = const Color(0xFFE53935); c.drawCircle(Offset(o.x - 7, o.y - 12), 2.6, _p); c.drawCircle(Offset(o.x, o.y - 18), 2.6, _p); c.drawCircle(Offset(o.x + 7, o.y - 11), 2.6, _p); } }

void _dino(Canvas c, Dino d) { final u = d.sp.size; c.save(); c.translate(d.x, d.y); if (cfg.shadow >= 2) { final r = Rect.fromCenter(center: const Offset(0, -2), width: u * 2.3, height: u * 0.6); _p.shader = const RadialGradient(colors: [Color(0x66000000), Color(0x00000000)]).createShader(r); c.drawOval(r, _p); _p.shader = null; } else if (cfg.shadow == 1) { _p.color = const Color(0x40000000); c.drawOval(Rect.fromCenter(center: const Offset(0, -2), width: u * 1.9, height: u * 0.42), _p); } if (!d.faceRight) c.scale(-1.0, 1.0); if (d.dead) { c.translate(0, -0.65 * u); c.rotate(pi); c.translate(0, 0.65 * u); } final lunge = d.atkAnim > 0 ? sin(d.atkAnim / 0.3 * pi) : 0.0; c.translate(lunge * 0.12 * u, 0); drawDinoShape(c, d.sp, d.col1, d.col2, d.anim, lunge, d.flash, d.dead); c.restore(); }

void _bar(Canvas c, double x, double y, double w, double frac, Color col) { _p.color = const Color(0x99000000); c.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(x, y), width: w + 2, height: 6), const Radius.circular(3)), _p); _p.color = col; c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(x - w / 2, y - 2, w * frac, 4), const Radius.circular(2)), _p); }

@override bool shouldRepaint(covariant GamePainter old) => true; }

class MiniMapPainter extends CustomPainter { final DinoGame g; MiniMapPainter(this.g) : super(repaint: g); @override void paint(Canvas c, Size size) { final ctr = size.center(Offset.zero); final r = size.width / 2; final p = Paint()..isAntiAlias = true; p.color = const Color(0x88000000); c.drawCircle(ctr, r, p); p.style = PaintingStyle.stroke; p.strokeWidth = 2; p.color = const Color(0xAAFFFFFF); c.drawCircle(ctr, r, p); p.style = PaintingStyle.fill; const range = 900.0; for (final d in g.dinos) { if (d.dead || identical(d, g.player)) continue; final dx = (d.x - g.player.x) / range * r, dy = (d.y - g.player.y) / range * r; if (dx * dx + dy * dy > (r - 3) * (r - 3)) continue; p.color = g.canPrey(d, g.player) ? Colors.redAccent : (d.sp.carn ? Colors.orangeAccent : Colors.lightGreenAccent); c.drawCircle(ctr + Offset(dx, dy), 3, p); } p.color = Colors.cyanAccent; c.drawCircle(ctr, 4, p); }

@override bool shouldRepaint(covariant MiniMapPainter old) => true; }

class PreviewPainter extends CustomPainter { final Species sp; final int variant; final double t; PreviewPainter(this.sp, this.variant, this.t); @override void paint(Canvas c, Size size) { final u = sp.size; final k = min(size.width / (u * 4.0), size.height / (u * (sp.neckY > 0.6 ? 3.0 : 2.0))); c.save(); c.translate(size.width * 0.52, size.height * 0.82); c.scale(k, k); c.drawOval(Rect.fromCenter(center: Offset.zero, width: u * 2.4, height: u * 0.5), Paint()..color = const Color(0x33000000)); drawDinoShape(c, sp, tintC(sp.c1, variant), tintC(sp.c2, variant), t * 2 * pi * 2, 0, 0, false); c.restore(); }

@override bool shouldRepaint(covariant PreviewPainter old) => true; }

