@override Widget build(BuildContext context) { final sp = kSpecies[sel]; return ListenableBuilder( listenable: cfg, builder: (context, ) => Scaffold( appBar: AppBar( title: Text(tr('choose')), actions: [ IconButton( icon: const Icon(Icons.settings), onPressed: () => Navigator.push(context, MaterialPageRoute(builder: () => const SettingsPage())), ), ], ), body: SafeArea( child: Row( children: [ Expanded( flex: 5, child: Column( children: [ Expanded( child: AnimatedBuilder( animation: ctl, builder: (_, __) => CustomPaint( painter: PreviewPainter(sp, variant, ctl.value), child: const SizedBox.expand(), ), ), ), Text(dinoName(sp.id), style: const TextStyle(fontSize: 20, fontWeight: FontWeight.bold)), const SizedBox(height: 4), Row( mainAxisAlignment: MainAxisAlignment.center, children: [ for (int i = 0; i < 3; i++) GestureDetector( onTap: () => setState(() => variant = i), child: Container( width: 26, height: 26, margin: const EdgeInsets.all(4), decoration: BoxDecoration( shape: BoxShape.circle, color: tintC(sp.c1, i), border: Border.all(color: variant == i ? Colors.white : Colors.white24, width: 3), ), ), ), ], ), Padding( padding: const EdgeInsets.fromLTRB(24, 4, 24, 8), child: Column( children: [ _stat(tr('hp'), sp.hp / 480, Colors.redAccent), _stat(tr('atk'), sp.atk / 46, Colors.orangeAccent), stat(tr('spd'), sp.speed / 200, Colors.lightBlueAccent), ], ), ), ], ), ), Expanded( flex: 4, child: Column( children: [ Expanded( child: ListView.builder( itemCount: kSpecies.length, itemBuilder: (context, i) { final s = kSpecies[i]; return Card( color: i == sel ? Colors.green.withValues(alpha: 0.35) : null, child: ListTile( dense: true, leading: Text(s.emoji, style: const TextStyle(fontSize: 26)), title: Text(dinoName(s.id)), subtitle: Text(s.carn ? tr('carn') : tr('herb')), onTap: () => setState(() => sel = i), ), ); }, ), ), Padding( padding: const EdgeInsets.all(12), child: SizedBox( width: double.infinity, child: FilledButton( onPressed: () => Navigator.push( context, Ma