// ============================================================================ // 10. GAME PAGE (loop, HUD, controls) // ============================================================================ class GamePage extends StatefulWidget { final Species sp; final int variant; const GamePage({super.key, required this.sp, required this.variant}); @override State createState() => _GamePageState(); }

class _GamePageState extends State with TickerProviderStateMixin { late DinoGame game = DinoGame(widget.sp, widget.variant); late GamePainter painter = GamePainter(game); late final Ticker _ticker = createTicker(_onTick); double _last = 0, _acc = 0, _since = 0; bool _menu = false;

@override void initState() { super.initState(); _ticker.start(); }

@override void dispose() { _ticker.dispose(); super.dispose(); }

void _onTick(Duration e) { final now = e.inMicroseconds / 1e6; final dt = now - _last; _last = now; if (dt <= 0) return; game.fpsN++; game.fpsT += dt; if (game.fpsT >= 1.0) { game.rawFps = game.fpsN / game.fpsT; game.fpsN = 0; game.fpsT = 0; } _acc += dt; _since += dt; final step = 1.0 / cfg.fps; if (_acc >= step - 0.002) { game.update(min(_since, 0.05)); _since = 0; _acc -= step; if (_acc < 0 || _acc > step) _acc = 0; game.repaint(); } }

void _restart() { setState(() { game = DinoGame(widget.sp, widget.variant); painter = GamePainter(game); _acc = 0; _since = 0; _menu = false; }); }

void _openMenu() { game.paused = true; game.joy = Offset.zero; game.run = false; game.atkHeld = false; setState(() => _menu = true); }

Widget _stat(String icon, double v, double max, Color col) { return Padding( padding: const EdgeInsets.only(bottom: 4), child: Row( mainAxisSize: MainAxisSize.min, children: [ Text(icon, style: const TextStyle(fontSize: 14)), const SizedBox(width: 4), SizedBox( width: 120, child: ClipRRect( borderRadius: BorderRadius.circular(4), child: LinearProgressIndicator( value: cl(v / max, 0, 1), minHeight: 9, backgroundColor: Colors.black54, valueColor: AlwaysStoppedAnimation(col), ), ), ), ], ), ); }

String _fmt(double s) { final m = (s ~/ 60).toString().padLeft(2, '0'); final r = (s.toInt() % 60).toString().padLeft(2, '0'); return '$m:$r'; }

@override Widget build(BuildContext context) { return ListenableBuilder( listenable: cfg, builder: (context, ) => Scaffold( backgroundColor: Colors.black, body: LayoutBuilder( builder: (context, cons) { final w = cons.maxWidth, h = cons.maxHeight; final pad = MediaQuery.of(context).padding; final p = game.player; return Stack( children: [ Positioned.fill( child: RepaintBoundary(child: CustomPaint(painter: painter)), ), JoystickLayer(game: game, size: Size(w, h)), Positioned( left: w * cfg.atkPos.dx - cfg.atkPx / 2, top: h * cfg.atkPos.dy - cfg.atkPx / 2, child: GameButton( size: cfg.atkPx, opacity: cfg.atkOpacity, icon: widget.sp.carn ? '🦷' : '💢', onDown: () { game.atkBuf = 0.25; game.atkHeld = true; }, onUp: () => game.atkHeld = false, ), ), Positioned( left: w * cfg.runPos.dx - cfg.runPx / 2, top: h * cfg.runPos.dy - cfg.runPx / 2, child: GameButton( size: cfg.runPx, opacity: cfg.atkOpacity, icon: '🏃', onDown: () => game.run = true, onUp: () => game.run = false, ), ), // HUD Positioned( left: 12 + pad.left, top: 8 + pad.top, child: AnimatedBuilder( animation: game, builder: (, __) => Column( crossAxisAlignment: CrossAxisAlignment.start, children: [ _stat('❤️', p.hp, p.maxHp, Colors.redAccent), _stat('🍖', p.hunger, 100, Colors.orangeAccent), _stat('⚡', p.stamina, 100, Colors.lightBlueAccent), if (cfg.showFps) Text('${game.rawFps.round()} FPS', style: const TextStyle(color: Colors.white70, fontSize: 12)), ], ), ), ), Positioned( right: 12 + pad.right, top: 8 + pad.top, child: Row( children: [ IconButton.filledTonal( onPressed: _openMenu, icon: const Icon(Icons.settings), ), const SizedBox(width: 8), SizedBox( width: 100, height: 100, child: CustomPaint(painter: MiniMapPainter(game)), ), ], ), ), // pause menu if (menu) Positioned.fill( child: Container( color: Colors.black54, child: Center( child: SizedBox( width: 260, child: Column( mainAxisSize: MainAxisSize.min, children: [ FilledButton( onPressed: () { game.paused = false; setState(() => menu = false); }, child: Text(tr('resume')), ), const SizedBox(height: 8), FilledButton.tonal( onPressed: () => Navigator.push( context, MaterialPageRoute(builder: () => SettingsPage(rawFps: game.rawFps)), ), child: Text(tr('settings')), ), const SizedBox(height: 8), OutlinedButton( onPressed: () => Navigator.popUntil(context, (r) => r.isFirst), child: Text(tr('menu')), ), ], ), ), ), ), ), // game over AnimatedBuilder( animation: game, builder: (, __) { if (game.phase != Phase.over) return const SizedBox.shrink(); return Positioned.fill( child: Container( color: Colors.black87, child: Center( child: Column( mainAxisSize: MainAxisSize.min, children: [ Text(tr('over'), style: const TextStyle(fontSize: 34, fontWeight: FontWeight.w900, color: Colors.redAccent)), const SizedBox(height: 8), Text('${tr('survived')}: ${_fmt(game.survived)}    ${tr('kills')}: ${game.kills}', style: const TextStyle(fontSize: 18)), const SizedBox(height: 16), SizedBox(width: 240, child: FilledButton(onPressed: _restart, child: Text(tr('retry')))), const SizedBox(height: 8), SizedBox( width: 240, child: OutlinedButton( onPressed: () => Navigator.pop(context), child: Text(tr('choose')), ), ), ], ), ), ), ); }, ), ], ); }, ), ), ); } }

class JoystickLayer extends StatefulWidget { final DinoGame game; final Size size; const JoystickLayer({super.key, required this.game, required this.size}); @override State createState() => _JoystickLayerState(); }

class _JoystickLayerState extends State { int? _pid; Offset? _origin; Offset _knob = Offset.zero;

double get _dia => cfg.joyPx; Offset get _fixed => Offset(widget.size.width * cfg.joyPos.dx, widget.size.height * cfg.joyPos.dy);

bool _nearBtn(Offset p) { final w = widget.size.width, h = widget.size.height; final a = Offset(w * cfg.atkPos.dx, h * cfg.atkPos.dy); final r = Offset(w * cfg.runPos.dx, h * cfg.runPos.dy); return (p - a).distance < cfg.atkPx * 0.75 || (p - r).distance < cfg.runPx * 0.75; }

bool _inRegion(Offset p) { if (cfg.joyFloating) { final w = widget.size.width; final inHalf = cfg.leftHanded ? p.dx > w * 0.5 : p.dx < w * 0.5; return inHalf && p.dy > widget.size.height * 0.2 && !_nearBtn(p); } return (p - _fixed).distance <= _dia * 0.8; }

void _down(PointerDownEvent e) { if (_pid != null || !_inRegion(e.localPosition)) return; _pid = e.pointer; _origin = cfg.joyFloating ? e.localPosition : _fixed; _move(e.localPosition); }

void _move(Offset p) { final o = _origin; if (o == null) return; var d = p - o; final maxR = _dia / 2; if (d.distance > maxR) d = d / d.distance * maxR; final v = d / maxR; widget.game.joy = v.distance < 0.1 ? Offset.zero : v; setState(() => _knob = d); }

void _up(PointerEvent e) { if (e.pointer != _pid) return; _pid = null; _origin = null; widget.game.joy = Offset.zero; setState(() => _knob = Offset.zero); }

@override Widget build(BuildContext context) { final base = _origin ?? _fixed; final r = _dia / 2; final active = _pid != null; final op = (cfg.joyFloating && !active) ? cfg.joyOpacity * 0.35 : cfg.joyOpacity; return Listener( behavior: HitTestBehavior.translucent, onPointerDown: _down, onPointerMove: (e) { if (e.pointer == _pid) _move(e.localPosition); }, onPointerUp: _up, onPointerCancel: _up, child: SizedBox.expand( child: Stack( children: [ Positioned( left: base.dx - r, top: base.dy - r, child: IgnorePointer( child: Opacity( opacity: op, child: Container( width: _dia, height: _dia, decoration: BoxDecoration( shape: BoxShape.circle, color: Colors.black38, border: Border.all(color: Colors.white70, width: 3), ), ), ), ), ), Positioned( left: base.dx + _knob.dx - r * 0.4, top: base.dy + _knob.dy - r * 0.4, child: IgnorePointer( child: Opacity( opacity: op, child: Container( width: r * 0.8, height: r * 0.8, decoration: const BoxDecoration(shape: BoxShape.circle, color: Colors.white54), ), ), ), ), ], ), ), ); } }

class GameButton extends StatefulWidget { final double size, opacity; final String icon; final VoidCallback onDown, onUp; const GameButton({ super.key, required this.size, required this.opacity, required this.icon, required this.onDown, required this.onUp, }); @override State createState() => _GameButtonState(); }

class _GameButtonState extends State { bool down = false;

void _d() { setState(() => down = true); widget.onDown(); if (cfg.haptic) HapticFeedback.selectionClick(); }

void _u() { if (!down) return; setState(() => down = false); widget.onUp(); }

@override void dispose() { if (down) widget.onUp(); super.dispose(); }

@override Widget build(BuildContext context) { return Listener( onPointerDown: (_) => d(), onPointerUp: () => u(), onPointerCancel: () => _u(), child: Opacity( opacity: widget.opacity, child: AnimatedScale( scale: down ? 0.9 : 1.0, duration: const Duration(milliseconds: 60), child: Container( width: widget.size, height: widget.size, alignment: Alignment.center, decoration: BoxDecoration( shape: BoxShape.circle, color: down ? Colors.white30 : Colors.black45, border: Border.all(color: Colors.white70, width: 3), ), child: Text(widget.icon, style: TextStyle(fontSize: widget.size * 0.45)), ), ), ), ); } }
